// 0.0.2 boards for the migration tests: generated by the real 0.0.2 code through the v0 driver with a
// fixed clock and random source, and frozen as JSON in test/fixtures/v0.0.2 so they outlive that code.

import { openDB } from 'idb';
import { vi } from 'vitest';
import type { LegacyData } from '../src/domain/legacy';
import { openBoard, type BoardDriver, type CardView } from './board-driver';

export interface LegacyFixture {
  legacy: LegacyData;
  // What 0.0.2 showed: the current branch, and each listed branch's name and cards.
  expected: { current: string; branches: Record<string, { name: string; cards: CardView[] }> };
}

// The 0.0.2 database exactly as DatabaseService created it (version 2, six stores).
export async function seedLegacy({ indexedDB: stores, localStorage: saved }: LegacyData) {
  for (const [key, value] of Object.entries(saved)) localStorage.setItem(key, value);
  if (Object.keys(stores).length === 0) return;
  const db = await openDB('kanban-light', 2, {
    upgrade(db) {
      db.createObjectStore('boards', { keyPath: 'id' }).createIndex('by-updated', 'updatedAt');
      const cards = db.createObjectStore('cards', { keyPath: 'id' });
      cards.createIndex('by-board', 'boardId');
      cards.createIndex('by-column', 'columnId');
      const events = db.createObjectStore('events', { keyPath: 'id' });
      events.createIndex('by-board', 'boardId');
      events.createIndex('by-timestamp', 'timestamp');
      db.createObjectStore('users', { keyPath: 'id' });
      db.createObjectStore('snapshots', { keyPath: 'id' }).createIndex('by-board', 'boardId');
      db.createObjectStore('plugins', { keyPath: 'id' });
    },
  });
  for (const [name, records] of Object.entries(stores)) for (const record of records) await db.put(name, record);
  db.close();
}

// Everything 0.0.2 kept, with the database's version, stores and indexes, for before/after comparison.
export async function dumpLegacy() {
  const saved: Record<string, string> = {};
  for (let i = 0; i < localStorage.length; i++) saved[localStorage.key(i)!] = localStorage.getItem(localStorage.key(i)!)!;
  const listed = await indexedDB.databases();
  if (!listed.some((db) => db.name === 'kanban-light')) return { localStorage: saved, database: null };
  const db = await openDB('kanban-light');
  const stores: Record<string, unknown> = {};
  for (const name of db.objectStoreNames) {
    const tx = db.transaction(name);
    stores[name] = { indexes: [...tx.store.indexNames], records: await tx.store.getAll() };
  }
  const database = { version: db.version, stores };
  db.close();
  return { localStorage: saved, database };
}

async function readLegacyStores(): Promise<Record<string, unknown[]>> {
  const db = await openDB('kanban-light');
  const stores: Record<string, unknown[]> = {};
  for (const name of db.objectStoreNames) stores[name] = await db.getAll(name);
  db.close();
  return stores;
}

const storedBranches = (): [string, { name: string }][] => JSON.parse(localStorage.getItem('kanban-branches')!).branches;

// Runs a 0.0.2 scenario with a fixed clock (one second per step) and a seeded random source.
export async function generate(
  scenario: (step: () => void, open: () => Promise<BoardDriver>) => Promise<{ board: BoardDriver; current: string; liveEdits?: (board: BoardDriver) => Promise<void> }>
): Promise<LegacyFixture> {
  vi.useFakeTimers({ toFake: ['Date'] });
  vi.setSystemTime(1_700_000_000_000);
  let seed = 1;
  const random = vi.spyOn(Math, 'random').mockImplementation(() => {
    seed = (seed * 16807) % 2147483647;
    return (seed - 1) / 2147483646;
  });
  const step = () => vi.setSystemTime(Date.now() + 1000);
  try {
    const { board, current, liveEdits } = await scenario(step, openBoard);
    // Visit every branch to record what 0.0.2 showed there, then end on the current branch.
    const branches: LegacyFixture['expected']['branches'] = {};
    const names = new Map(storedBranches().map(([id, value]) => [id, value.name]));
    for (const [pick, id] of board.branches().entries()) {
      step();
      await board.switchTo(pick);
      branches[id] = { name: names.get(id)!, cards: JSON.parse(board.view()) };
    }
    step();
    await board.switchTo(board.branches().indexOf(current));
    if (liveEdits) {
      await liveEdits(board);
      branches[current].cards = JSON.parse(board.view());
    }
    const saved: Record<string, string> = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)!;
      if (key.startsWith('kanban')) saved[key] = localStorage.getItem(key)!;
    }
    return JSON.parse(JSON.stringify({ legacy: { indexedDB: await readLegacyStores(), localStorage: saved }, expected: { current, branches } }));
  } finally {
    random.mockRestore();
    vi.useRealTimers();
  }
}

// Each scenario returns the board, the branch to end on, and edits made after the last switch.
type Scenario = Parameters<typeof generate>[0];

const branchNamed = (board: BoardDriver, name: string) => board.branches()[storedBranches().findIndex(([, value]) => value.name === name)];

export const SCENARIOS: Record<string, Scenario> = {
  async plain(step, open) {
    const board = await open();
    for (const [title, column] of [['Write docs', 'todo'], ['Fix login', 'in-progress'], ['Ship', 'done']]) {
      step();
      await board.create(title, column);
    }
    step();
    await board.update(1, { title: 'Fix login and logout', columnId: 'review' });
    step();
    await board.remove(0);
    return { board, current: 'main' };
  },

  async 'branch-of-branch'(step, open) {
    const board = await open();
    step();
    await board.create('On main', 'todo');
    step();
    await board.branch('feature');
    step();
    await board.create('On feature', 'backlog');
    step();
    await board.branch('feature-ui');
    step();
    await board.create('On feature-ui', 'review');
    step();
    await board.switchTo(0);
    step();
    await board.update(0, { title: 'Edited on main' });
    return { board, current: branchNamed(board, 'feature') };
  },

  async recovered(step, open) {
    let board = await open();
    step();
    await board.create('Kept on main', 'todo');
    step();
    await board.branch('lost');
    step();
    await board.create('On the lost branch', 'done');
    // An older version could leave the pointer on a branch that is not listed: 0.0.2 lists it as `recovered`.
    const saved = JSON.parse(localStorage.getItem('kanban-branches')!);
    saved.branches = saved.branches.filter(([id]: [string]) => id === 'main');
    localStorage.setItem('kanban-branches', JSON.stringify(saved));
    step();
    board = await board.reload();
    return { board, current: board.activeBranch() };
  },

  async 'phantom-snapshot'(step, open) {
    let board = await open();
    step();
    await board.create('On main', 'todo');
    step();
    await board.branch('temp');
    step();
    await board.create('Only on temp', 'todo');
    step();
    await board.switchTo(0);
    // The branch leaves the list but its snapshots stay in the database.
    const saved = JSON.parse(localStorage.getItem('kanban-branches')!);
    saved.branches = saved.branches.filter(([id]: [string]) => id === 'main');
    localStorage.setItem('kanban-branches', JSON.stringify(saved));
    step();
    board = await board.reload();
    return { board, current: 'main' };
  },

  async 'live-edits'(step, open) {
    const board = await open();
    step();
    await board.create('Snapshotted', 'todo');
    step();
    await board.branch('idea');
    step();
    await board.create('On idea', 'todo');
    return {
      board,
      current: 'main',
      // Made after the last switch, so they are in the live cards store but in no snapshot.
      async liveEdits(board) {
        step();
        await board.create('Live only', 'backlog');
        step();
        await board.update(0, { columnId: 'done' });
      },
    };
  },

  async 'repeated-names'(step, open) {
    const board = await open();
    step();
    await board.create('Shared', 'todo');
    for (const name of ['idea', 'idea', 'Idea']) {
      step();
      await board.switchTo(0);
      step();
      await board.branch(name);
      step();
      await board.create(`Made on ${name} ${board.branches().length - 1}`, 'todo');
    }
    return { board, current: 'main' };
  },

  async 'over-limit'(step, open) {
    const board = await open();
    const { useKanbanStore } = await import('../src/store/useKanbanStore');
    const tags = [...Array.from({ length: 22 }, (_, i) => `tag-${i}`), 'x'.repeat(60), '  spaced  ', 'tag-0', ' tag-1'];
    step();
    await useKanbanStore.getState().createCard(`  ${'Long title '.repeat(45)}  `, 'todo', {
      description: '  Keep **these** spaces  \n',
      assignee: '  Ann  ',
      tags,
    });
    step();
    await useKanbanStore.getState().createCard('Nobody', 'backlog', { assignee: 'Unassigned' });
    step();
    await board.create('Plain', 'done');
    return { board, current: 'main' };
  },

  async 'older-than-main'(step, open) {
    // main is missing from the list, so 0.0.2 recreates it now: `idea` is older than main.
    const idea = { id: 'branch-1600000000000', name: 'idea', parentId: 'main', boardSnapshot: null, createdAt: 1_600_000_000_000, lastCommit: 'init', author: 'current-user' };
    localStorage.setItem('kanban-branches', JSON.stringify({ branches: [[idea.id, idea]], currentBranch: 'main' }));
    const board = await open();
    step();
    await board.create('On main', 'todo');
    step();
    await board.switchTo(board.branches().indexOf(idea.id));
    step();
    await board.create('On idea', 'done');
    return { board, current: idea.id };
  },
};
